===OwnerIdentity===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}, the derived value all duplicate
 * detection is expressed through: {@code normalizedTelephone + '|' + (email or empty) + '|' +
 * householdId}. Two owners are duplicates only when their whole identityKey is equal, so members of
 * the same household (same householdId) with different telephones have distinct keys.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    public static String key(Owner owner) {
        return orEmpty(owner.getTelephone()) + "|" + orEmpty(owner.getEmail()) + "|"
                + orEmpty(owner.getHouseholdId());
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}
===FlagBulkSignup===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags {@code bulkSignupWarning} true when more than {@value #BULK_THRESHOLD} owners have already
 * been created today (by registrationDate), otherwise false. Runs before Save so the flag is
 * persisted and read back on GET, and counts only the owners that existed before this create.
 */
public class FlagBulkSignup {

    private static final int BULK_THRESHOLD = 80;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        LocalDate today = owner.getRegistrationDate();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (today.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        owner.setBulkSignupWarning(count > BULK_THRESHOLD);
    }
}
