3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	public class BuildOwner {
11	
12	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
13	            Out<Boolean> sharesHousehold) throws InvalidTelephoneException {
14	        Owner owner = ownerMapper.toOwner(request);
15	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
16	        owner.setTelephone(toE164(owner.getTelephone()));
17	        java.time.LocalDate effective = owner.getRegistrationDate() == null
18	                ? java.time.LocalDate.now() : owner.getRegistrationDate();
19	        owner.setRegistrationDate(BusinessDay.roll(effective));
20	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
21	        built.set(owner);
22	    }
23	
24	    /**
25	     * Normalizes a telephone to E.164: strip spaces, dashes and brackets; keep a leading '+' with its
26	     * country code, otherwise assume '+61' and drop a single leading '0' from the national digits.
27	     * Requires 8 to 15 digits after the '+'.
28	     */
29	    private static String toE164(String raw) throws InvalidTelephoneException {
30	        String cleaned = (raw == null ? "" : raw).replaceAll("[\\s\\-()\\[\\]]", "");
31	        String digits;
32	        if (cleaned.startsWith("+")) {
33	            digits = cleaned.substring(1);
34	        } else {
35	            digits = "61" + (cleaned.startsWith("0") ? cleaned.substring(1) : cleaned);
36	        }
37	        if (!digits.matches("\\d{8,15}") || !hasValidNationalLength(digits)) {
38	            throw new InvalidTelephoneException(raw);
39	        }
40	        return "+" + digits;
41	    }
42	
43	    /**
44	     * Checks the national-number length for the recognised country codes: '+61' requires 9 national
45	     * digits and '+1' requires 10. Other country codes have no per-country rule here.
46	     */
47	    private static boolean hasValidNationalLength(String digits) {
48	        if (digits.startsWith("61")) {
49	            return digits.length() - 2 == 9;
50	        }
51	        if (digits.startsWith("1")) {
52	            return digits.length() - 1 == 10;
53	        }
54	        return true;
55	    }
56	}
