3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * When the request opts in with {@code sharesHousehold: true}, gives the new owner a stable shared
13	 * {@code householdId} derived from the household's normalized last name and address, and back-fills
14	 * the same id onto any existing owner in that household that lacks one. Deterministic derivation means
15	 * every owner joining the same household is assigned an identical, non-blank identifier. Runs after
16	 * {@link EnsureUniqueHousehold} and before the owner is saved.
17	 */
18	public class AssignHousehold {
19	
20	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
21	        if (!Boolean.TRUE.equals(sharesHousehold)) {
22	            return;
23	        }
24	        String householdId = deriveId(owner.getLastName(), owner.getAddress());
25	        owner.setHouseholdId(householdId);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (existing.getHouseholdId() == null && sameHousehold(owner, existing)) {
28	                existing.setHouseholdId(householdId);
29	                ownerRepository.save(existing);
30	            }
31	        }
32	    }
33	
34	    private static boolean sameHousehold(Owner a, Owner b) {
35	        return normalize(a.getLastName()).equals(normalize(b.getLastName()))
36	                && normalize(a.getAddress()).equals(normalize(b.getAddress()));
37	    }
38	
39	    /** Stable {@code HH-<12 hex>} identifier for the household keyed by normalized last name and address. */
40	    private static String deriveId(String lastName, String address) {
41	        String key = normalize(lastName) + "|" + normalize(address);
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder("HH-");
45	            for (int i = 0; i < 6; i++) {
46	                sb.append(String.format("%02X", digest[i]));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException ex) {
51	            throw new IllegalStateException(ex);
52	        }
53	    }
54	
55	    private static String normalize(String value) {
56	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
57	    }
58	}
