3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	
8	/**
9	 * Rejects a new owner whose whole {@link OwnerIdentity#key(Owner) identityKey} equals an existing
10	 * owner's. This consolidates the former separate telephone, email and household checks into one key,
11	 * so an exact full-key match is the only conflict. Runs after {@link AssignHousehold} (which fixes the
12	 * householdId part) and before Save, so the collision is a 409, not a persisted duplicate.
13	 */
14	public class EnsureUniqueIdentity {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateTelephoneException {
17	        String identityKey = OwnerIdentity.key(owner);
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (identityKey.equals(OwnerIdentity.key(existing))) {
20	                throw new DuplicateTelephoneException(owner.getTelephone());
21	            }
22	        }
23	    }
24	}
