7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code customerCode} as {@code <REGION>-<HASH8>}: the region code derived from
12	 * the postcode (see {@link OwnerLocality#forPostcode}) and the first eight upper-case hex characters
13	 * of SHA-256 over the normalized telephone (set by {@link BuildOwner}) concatenated with the last
14	 * name. The code is a pure function of the owner's identity, so it carries no sequence number.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner) {
19	        String region = OwnerLocality.forPostcode(owner.getPostcode(), owner.getCity());
20	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
21	        owner.setCustomerCode(region + "-" + hash8);
22	    }
23	
24	    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
25	    private static String hash8(String value) {
26	        try {
27	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(8);
29	            for (int i = 0; i < 4; i++) {
30	                sb.append(String.format("%02X", digest[i]));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException ex) {
35	            throw new IllegalStateException(ex);
36	        }
37	    }
38	}
