7	
8	/**
9	 * Rejects a new owner whose city already contains {@value #CAPACITY} or more owners, comparing city
10	 * names case-insensitively. Runs before Save so a full city is a 409, not a persisted overflow.
11	 */
12	public class EnsureCityCapacity {
13	
14	    private static final int CAPACITY = 50;
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws CityAtCapacityException {
17	        String city = owner.getCity();
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
21	                count++;
22	            }
23	        }
24	        if (count >= CAPACITY) {
25	            throw new CityAtCapacityException(city, count);
26	        }
27	    }
28	}
